// Regenerates dawn/vendor/post.js from the three examples/jsm sources (GAP §1).
//
// The post chain — EffectComposer, RenderPass, ShaderPass, UnrealBloomPass,
// OutputPass and their shader dependencies — ships as examples/jsm ES modules
// that import from 'three'. The viewer vendors three.js inline and publishes
// it on window.THREE (dawn/viewer.py:_inline_three), so the same wiring is
// resolved here, once, offline: all files land in a single module scope in
// dependency order, their 'three' imports become one destructure of
// window.THREE, their relative imports dissolve (same scope), and the classes
// the template needs are published on window.__POST.
//
// Run from the repo root after bumping the three devDependency (which must
// match the vendored r-version, currently r178):
//   node dawn/vendor/build-post.mjs
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const jsm = join(root, "node_modules", "three", "examples", "jsm");
const rev = JSON.parse(
  readFileSync(join(root, "node_modules", "three", "package.json"))).version;

// Dependency order: each file only uses names defined above it.
const FILES = [
  "postprocessing/Pass.js",
  "postprocessing/MaskPass.js",
  "shaders/CopyShader.js",
  "shaders/LuminosityHighPassShader.js",
  "shaders/OutputShader.js",
  "postprocessing/ShaderPass.js",
  "postprocessing/RenderPass.js",
  "postprocessing/EffectComposer.js",
  "postprocessing/UnrealBloomPass.js",
  "postprocessing/OutputPass.js",
];
const PUBLISH = ["EffectComposer", "RenderPass", "ShaderPass",
                 "UnrealBloomPass", "OutputPass", "FullScreenQuad"];

const threeNames = new Set();
let body = "";
for (const f of FILES) {
  let src = readFileSync(join(jsm, f), "utf8");
  // 'three' imports: collect the names, drop the statement.
  src = src.replace(/import\s*\{([^}]*)\}\s*from\s*['"]three['"];?/g,
    (_, names) => {
      for (const n of names.split(",")) {
        const t = n.trim();
        if (t) threeNames.add(t);
      }
      return "";
    });
  // Relative imports dissolve: everything shares one scope.
  src = src.replace(/import\s*\{[^}]*\}\s*from\s*['"]\.[^'"]*['"];?/g, "");
  // Exports likewise.
  src = src.replace(/export\s*\{[^}]*\};?/g, "");
  body += `\n// ---- ${f} (three r${rev}) ----\n` + src;
}

const out =
  `// Generated by dawn/vendor/build-post.mjs from three r${rev} examples/jsm.\n` +
  `// Do not edit by hand; see that script's header.\n` +
  `const { ${[...threeNames].sort().join(", ")} } = window.THREE;\n` +
  body +
  `\nwindow.__POST = { ${PUBLISH.join(", ")} };\n`;

if (out.includes("</script")) {
  throw new Error("post.js would break its inline <script>; escape it first");
}
writeFileSync(join(root, "dawn", "vendor", "post.js"), out);
console.log(`post.js written: ${(out.length / 1024).toFixed(1)} KB, ` +
            `${threeNames.size} three imports, three r${rev}`);
